// Resolve: the will to keep going, 0..100. Slower than mood: mood is how today feels,
// resolve is what the days add up to.
//
// Every dawn it drifts with mood (a good day +, a bad day -); loneliness and a poor bed
// get in through mood (wellbeing.ts).
// Events move it directly (steel()): a request seen through, someone found, a confession
// made lift it; a friend's death, a silent radio cut it.
//   breaking (under BREAKING)  might walk away in the night; under your control, freezes
//                              in a fight now and then
//   steeled (STEELED or more)  doesn't break down
// It starts near the middle, a little different for each (a hash of their id).
#nullable disable warnings
namespace LoonieRoo.Sim;

public static partial class Resolve
{

    public const int RESOLVE_MAX = 100;

    public const int BREAKING = 20;

    public const int STEELED = 80;

    /// <summary>Mood points above or below MOOD_BASE per point of resolve at dawn.</summary>
    public const int MOOD_PER_POINT = 8;

    /// <summary>The most a single dawn can move it.</summary>
    public const int DAWN_LIMIT = 4;

    /// <summary>Chance of freezing on a swing, while breaking.</summary>
    public const double FREEZE_CHANCE = 0.25;

    public static double startingResolve(string id)
    {
        return 40 + JsMath.floor(Hash.hashRoll(Hash.idNumber(id), 2021.0) * 21);
    }

    public static void steel(Survivor s, int by)
    {
        s.resolve = JsMath.max(0, JsMath.min(RESOLVE_MAX, s.resolve + by));
    }

    public static bool isBreaking(Survivor s)
    {
        return s.resolve < BREAKING;
    }

    public static bool isSteeled(Survivor s)
    {
        return s.resolve >= STEELED;
    }

    public static string describeResolve(Survivor s)
    {
        return Js.T(isBreaking(s)) ? "breaking" : (Js.T(isSteeled(s)) ? "steeled" : ((s.resolve < 40) ? "wavering" : "steady"));
    }

    /// <summary>Dawn: drift with mood. Returns those who walk away (the caller removes them).</summary>
    public static List<Survivor> dawnResolve(SimState state)
    {
        if ((state.tick == 0) || ((state.tick % Time.DAY_LENGTH) != 0))
        {
            return [];
        }
        List<Survivor> leaving = [];
        foreach (var s in Js.Iter(state.survivors))
        {
            var drift = JsMath.round(((double)((Mood.mood(state, s) - Mood.MOOD_BASE)) / (MOOD_PER_POINT)));
            steel(s, JsMath.max(-DAWN_LIMIT, JsMath.min(DAWN_LIMIT, drift)));
            if ((!Js.T(isBreaking(s)) || (state.control?.survivorId == s.id)) || (s.childUntil != null))
            {
                continue;
            }
            if (Hash.hashRoll(Hash.idNumber(s.id), state.tick, 7847.0) < ((double)((BREAKING - s.resolve)) / ((2 * BREAKING))))
            {
                leaving.push(s);
            }
        }
        foreach (var s in Js.Iter(leaving))
        {
            Events.logEvent(state, $"{Js.Str(s.name)} walked away in the night. They couldn't do it any more.");
        }
        return leaving;
    }

    /// <summary>Breaking, and you're in control: a swing may freeze.</summary>
    public static bool freezes(SimState state, Survivor s)
    {
        return Js.T(isBreaking(s)) && (Hash.hashRoll(Hash.idNumber(s.id), state.tick, 0xf2) < FREEZE_CHANCE);
    }
}
